import math

# Output column mapping: 0,0,1,2,2
# Let me find formula for this
col_mapping = [0, 0, 1, 2, 2]  # in_col for each out_col

print("Testing column mapping formulas:")
for formula_str in [
    "floor(j*2/5 + 0.5)",
    "floor(j*3/5)",
    "floor((j+1)*2/5)",
    "floor(j*5/7)",
    "floor((j+0.5)*3/5)",
    "floor((j+0.5)*2/3)",
    "ceil(j*2/5 - 0.2)",
    "floor((j + 2/3) * 2/5)",
]:
    result = []
    for j in range(5):
        try:
            if "floor" in formula_str:
                if "j*2/5" in formula_str and "+0.5" in formula_str:
                    val = math.floor(j * 2 / 5 + 0.5)
                elif "j*3/5" in formula_str:
                    val = math.floor(j * 3 / 5)
                elif "(j+1)*" in formula_str:
                    parts = formula_str.split("*")
                    scale = float(parts[1].split("/")[0])
                    mult = float(formula_str.split("*")[1].split("(")[1])
                    pos = int(mult)
                    if pos == 2:
                        val = math.floor((j + 1) * 2 / 5)
                    elif pos == 3:
                        val = math.floor((j + 1) * 3 / 5)
                elif "j*5/7" in formula_str:
                    val = math.floor(j * 5 / 7)
                elif "(j+0.5)*" in formula_str:
                    if "3/5" in formula_str:
                        val = math.floor((j + 0.5) * 3 / 5)
                    elif "2/3" in formula_str:
                        val = math.floor((j + 0.5) * 2 / 3)
                elif "ceil(j*2/5" in formula_str:
                    val = math.ceil(j * 2 / 5 - 0.2)
                elif "(j + 2/3)" in formula_str:
                    val = math.floor((j + 2/3) * 2/5)
                elif "j*0.5" in formula_str or "/5)" in formula_str:
                    # Try j*something/5+0.5
                    val = math.floor(j * 4 / 5 + 0.5)
                else:
                    val = j
            elif "ceil" in formula_str:
                val = math.ceil(j * 2 / 5 - 0.2)
            else:
                val = j

            result.append(int(val))
        except:
            break
    if result == col_mapping:
        print(f"  ✓ {formula_str}")
    else:
        print(f"  ✗ {formula_str}: {result}")

